            stone: Stone::granite(),
            wood_lit: hex("#a08a70"),
            wood_shade: hex("#3a332d"),
            ripple: 0.035,
        },
        Light {
            name: "dawn",
            sun: Sun::deg(18.0, -4.0),
            sky_top: hex("#56627b"),
            sky_low: hex("#b9a7a2"),
            glow: hex("#efcb95"),
            glow_amt: 0.9,
