        &Gesture::new(vec![(266.0, 442.0), (350.0, 428.0), (434.0, 443.0)])
            .pressure(0.6, 0.6)
            .ramps(0.1, 0.1)
            .orient(Orient::Across),
        None,
    );

    // 2. Natural snow blankets draping over the upper dome of each erratic boulder
    for &(bx, by, bw) in &[
        (215.0, 605.0, 46.0), // Boulder 1 (center 605, top ~570)
        (460.0, 600.0, 50.0), // Boulder 2 (center 600, top ~562)
        (540.0, 625.0, 36.0), // Boulder 3 (center 625, top ~595)
    ] {
        let top_y = by - bw * 0.38;
        let pts = vec![
            (bx - bw * 0.42, top_y + 8.0),
            (bx - bw * 0.15, top_y + 1.0),
            (bx + bw * 0.15, top_y + 1.0),
            (bx + bw * 0.42, top_y + 7.0),
        ];
        let mut b_held = Held::new(Tool::round_sable(bw * 0.32), rng.next_u64());
        b_held.load(snow_cap_paint, 0.9);
        c.drag(&mut b_held, &Gesture::new(pts).pressure(0.6, 0.85).ramps(0.2, 0.2).orient(Orient::Across), None);

        // Lit crest
        let cr_pts = vec![
            (bx - bw * 0.22, top_y + 3.0),
            (bx, top_y),
            (bx + bw * 0.22, top_y + 2.5),
        ];
        let mut c_held = Held::new(Tool::rigger(0.9), rng.next_u64());
        c_held.load(snow_crest_paint, 0.85);
        c.drag(&mut c_held, &Gesture::new(cr_pts).pressure(0.5, 0.4).ramps(0.1, 0.1).orient(Orient::Across), None);
    }

    c.dry();
}

