// ------------------------------------------------------------- stage: snow on motifs
if o.stage("snow on motifs", &mut c, &mut rng) {
    let snow_cap_paint = pal.paint(hex("#ede8dd"), 0.15).with_hiding(0.96);
    let snow_crest_paint = pal.paint(hex("#f3efe6"), 0.1).with_hiding(0.98);
    let snow_shade_paint = pal.paint(hex("#979cb0"), 0.2).with_hiding(0.9);

    // 1. Physically mapped snow on upward-facing stone planes (capstone, upright tops, boulders)
    let stone_snow_m = stone_form.mask(|s| {
        if s.n[1] < -0.32 && s.z > -20.0 {
            ((-s.n[1] - 0.32) / 0.68).clamp(0.0, 1.0)
        } else {
            0.0
        }
    });
    let stone_snow_handling = st.body()
        .color(|_, y| {
            if y < 450.0 { hex("#eee9df") } else { hex("#ded8cb") }
        })
        .angle(|_, _| 0.04)
        .coverage(4.4)
        .medium(0.18);
    c.work(&stone_snow_m, &stone_snow_handling, o.seed * 113 + 5);

    // 2. Thick sculpted snow cornice on top of the dolmen capstone
    let cap_pts = vec![
        (260.0, 436.0),
        (305.0, 421.0),
        (350.0, 416.0),
        (395.0, 422.0),
        (440.0, 438.0),
    ];
    let mut sn_held = Held::new(Tool::round_sable(15.0), rng.next_u64());
    sn_held.load(snow_cap_paint, 1.0);
    c.drag(
        &mut sn_held,
        &Gesture::new(cap_pts)
            .pressure(0.7, 0.95)
            .ramps(0.2, 0.2)
            .orient(Orient::Across),
        None,
    );

    // Crisp windward crest highlight on the capstone snow cornice
    let crest_pts = vec![
        (275.0, 430.0),
        (345.0, 418.0),
        (425.0, 432.0),
    ];
    let mut cr_held = Held::new(Tool::rigger(1.2), rng.next_u64());
    cr_held.load(snow_crest_paint, 0.85);
    c.drag(&mut cr_held, &Gesture::new(crest_pts).pressure(0.6, 0.4).ramps(0.1, 0.2).orient(Orient::Across), None);

    // Soft undercut shadow beneath the capstone snow overhang
    let mut sn_sh_held = Held::new(Tool::rigger(1.4), rng.next_u64());
    sn_sh_held.load(snow_shade_paint, 0.7);
    c.drag(
        &mut sn_sh_held,
        &Gesture::new(vec![(264.0, 442.0), (350.0, 428.0), (436.0, 444.0)])
            .pressure(0.6, 0.6)
            .ramps(0.1, 0.1)
            .orient(Orient::Across),
        None,
    );

    // 3. Ground snowdrifts banking against the foot of the stones, sinking them into the snow
    for &(sx, sy, sw) in &[
        (295.0, 560.0, 28.0),
        (405.0, 568.0, 32.0),
        (215.0, 622.0, 34.0),
        (460.0, 618.0, 38.0),
        (540.0, 632.0, 24.0),
    ] {
        let pts = vec![(sx - sw * 0.5, sy + 3.0), (sx, sy - 1.0), (sx + sw * 0.5, sy + 4.0)];
        let mut d_held = Held::new(Tool::round_sable(sw * 0.35), rng.next_u64());
        d_held.load(snow_cap_paint, 0.75);
        c.drag(&mut d_held, &Gesture::new(pts).pressure(0.5, 0.7).ramps(0.2, 0.2).orient(Orient::Across), None);
    }

    c.dry();
}

